function handleBooking(e) {
    e.preventDefault();
    if (!currentUser) return openModal('login');

    const platform = document.getElementById('booking-platform').value === 'Other'
        ? document.getElementById('booking-platform-other').value
        : document.getElementById('booking-platform').value;

    const data = {
        id: editingBookingId || ('BK-' + String(Math.floor(Math.random() * 9000) + 1000)),
        userId: currentUser.id,
        userName: currentUser.name,
        concertId: activeConcertId,
        concertName: concerts.find(x => x.id === activeConcertId)?.title || 'เธเธญเธเน€เธชเธดเธฃเนเธ•',

        platform: platform,
        user: document.getElementById('booking-user').value,
        pass: document.getElementById('booking-pass').value,
        email: document.getElementById('booking-email').value,
        phone: document.getElementById('booking-phone').value,
        twitter: document.getElementById('booking-twitter').value,
        member: document.getElementById('booking-member').value,
        showDate: document.getElementById('booking-showdate').value,
        zone1: document.getElementById('booking-zone-1').value,
        zone2: document.getElementById('booking-zone-2').value,
        price1: document.getElementById('booking-price-1').value,
        price2: document.getElementById('booking-price-2').value,
        qty: parseInt(document.getElementById('booking-quantity').value),
        payment: document.getElementById('booking-payment').value,
        nameT: document.getElementById('booking-name-t').value,
        surnameT: document.getElementById('booking-surname-t').value,
        note: document.getElementById('booking-note').value,

        status: 'Pending',
        total: (parseInt(document.getElementById('booking-price-1').value) || 0) * parseInt(document.getElementById('booking-quantity').value),
        date: editingBookingId ? (bookings.find(x => x.id === editingBookingId)?.date || new Date().toLocaleDateString('th-TH')) : new Date().toLocaleDateString('th-TH')
    };

    if (editingBookingId) {
        const idx = bookings.findIndex(x => x.id === editingBookingId);
        if (idx !== -1) {
            bookings[idx] = data;
            showToast(t('toast_edit_success'));
        }
    } else {
        bookings.unshift(data);
        showToast(t('toast_booking_sent'));
    }

    // Push to Firebase
    db.ref('bookings').set(bookings);
    closeModal('booking');
    setTimeout(() => switchBottomNav('profile'), 1000);
}

