function renderProfile() {
    if (!currentUser) return;
    const container = document.getElementById('my-tickets-list');
    const mine = bookings.filter(b => b.userId === currentUser.id);

    if (mine.length === 0) {
        container.innerHTML = `<div class="empty-state"><i class="fas fa-ticket-alt"></i><p>${t('empty_no_booking')}</p></div>`;
        return;
    }

    container.innerHTML = mine.map(b => {
        const concert = concerts.find(c => c.id == b.concertId);
        const concertImg = concert ? concert.img : 'https://images.unsplash.com/photo-1540039155733-5bb30b53aa14?auto=format&fit=crop&w=800&q=80';

        return `
        <div class="ticket-card">
            <div class="ticket-image">
                <img src="${concertImg}" alt="${b.concertName}">
                <div class="ticket-date-tag">${b.date}</div>
            </div>
            <div class="ticket-content">
                <div class="ticket-title">${b.concertName}</div>
                <div class="ticket-details-grid">
                    <div class="t-detail"><span>PLATFORM</span>${b.platform}</div>
                    <div class="t-detail"><span>ZONE</span>${b.zone1}</div>
                    <div class="t-detail"><span>QTY</span>${b.qty} ${t('unit_ticket')}</div>
                    <div class="t-detail"><span>PAYMENT</span>${b.payment}</div>
                </div>
                <div class="ticket-footer">
                    <span class="badge ${b.status === 'Confirmed' ? 'badge-success' : b.status === 'Failed' ? 'badge-failed' : 'badge-pending'}">
                        ${b.status === 'Confirmed' ? t('ticket_confirmed') : b.status === 'Failed' ? t('ticket_failed') : t('ticket_pending')}
                    </span>
                    ${b.status === 'Pending' ? `<button class="btn-edit-ticket" onclick="editBooking('${b.id}')"><i class="fas fa-edit"></i> ${t('ticket_edit_btn')}</button>` : ''}
                </div>
            </div>
        </div>`;
    }).join('');
}

// ============================================================
// ADMIN MANAGEMENT
// ============================================================
let editingEventId = null;

function getStatusLabel(status) {
    if (status === 'open') return `<span style="color:#10b981;font-weight:700">${t('badge_open')}</span>`;
    if (status === 'coming') return `<span style="color:#f59e0b;font-weight:700">${t('badge_coming')}</span>`;
    return '<span style="color:#999">N/A</span>';
}

function openAddEventModal() {
    editingEventId = null;
    document.getElementById('event-modal-title').innerText = t('admin_event_add_title');
    document.getElementById('event-form').reset();
    openModal('event');
}

function openEditEventModal(id) {
    editingEventId = id;
    const c = concerts.find(x => x.id === id);
    if (!c) return;

    document.getElementById('event-modal-title').innerText = t('admin_event_edit_title');
    document.getElementById('event-title').value = c.title;
    document.getElementById('event-price').value = c.price;
    document.getElementById('event-img').value = c.img;
    document.getElementById('event-quantity').value = c.quantity;
    document.getElementById('event-status').value = c.status || '';
    document.getElementById('event-recommended').value = c.recommended || 'no';
    document.getElementById('event-date').value = c.date;
    document.getElementById('event-venue').value = c.venue;

    openModal('event');
}

function handleEventSubmit(e) {
    e.preventDefault();
    const data = {
        title: document.getElementById('event-title').value,
        price: document.getElementById('event-price').value,
        img: document.getElementById('event-img').value,
        quantity: parseInt(document.getElementById('event-quantity').value),
        status: document.getElementById('event-status').value,
        recommended: document.getElementById('event-recommended').value,
        date: document.getElementById('event-date').value,
        venue: document.getElementById('event-venue').value
    };

    if (editingEventId) {
        const index = concerts.findIndex(x => x.id == editingEventId);
        concerts[index] = { ...concerts[index], ...data };
        showToast(t('toast_save_success'));
    } else {
        const maxId = concerts.length > 0 ? Math.max(...concerts.map(x => x.id)) : 0;
        const newEvent = { id: maxId + 1, ...data };
        concerts.push(newEvent);
        showToast(t('toast_add_success'));
    }

    // Push to Firebase
    db.ref('concerts').set(concerts);
    closeModal('event');
    renderConcerts('concert-list');
    renderConcerts('all-events-list');
    renderAdminEvents();
    updateAdminStats();
}

function renderAdminEvents() {
    const tableBody = document.querySelector('#admin-events-table tbody');
    if (!tableBody) return;
    tableBody.innerHTML = '';

    concerts.forEach(c => {
        const row = document.createElement('tr');
        row.dataset.id = c.id;
        row.innerHTML = `
            <td>
                <div style="display:flex; align-items:center; gap:8px;">
                    <img src="${c.img}" style="width:40px; height:40px; border-radius:8px; object-fit:cover;" onerror="this.src='https://via.placeholder.com/40'">
                    <span style="max-width:100px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${c.title}</span>
                </div>
            </td>
            <td>เธฟ${typeof c.price === 'number' ? c.price.toLocaleString() : c.price}</td>
            <td>${c.quantity}</td>
            <td>${getStatusLabel(c.status)}</td>
            <td>
                <div style="display:flex; gap:5px; align-items:center;">
                    <button class="btn-primary btn-edit-event" data-id="${c.id}" style="width:30px;height:30px;padding:0;font-size:0.7rem;"><i class="fas fa-edit"></i></button>
                    <button class="btn-delete-event" data-id="${c.id}" data-confirm="0" style="width:30px;height:30px;padding:0;font-size:0.7rem;background:#ff7c5c;border:none;border-radius:8px;color:white;cursor:pointer;"><i class="fas fa-trash"></i></button>
                </div>
            </td>
        `;
        tableBody.appendChild(row);
    });

    tableBody.onclick = function (e) {
        const editBtn = e.target.closest('.btn-edit-event');
        const deleteBtn = e.target.closest('.btn-delete-event');
        if (editBtn) openEditEventModal(parseInt(editBtn.dataset.id));
        if (deleteBtn) {
            const confirmed = deleteBtn.dataset.confirm === '1';
            if (!confirmed) {
                deleteBtn.innerHTML = '<i class="fas fa-check"></i>';
                deleteBtn.style.background = '#dc2626';
                deleteBtn.dataset.confirm = '1';
                setTimeout(() => {
                    if (deleteBtn.dataset.confirm === '1') {
                        deleteBtn.innerHTML = '<i class="fas fa-trash"></i>';
                        deleteBtn.style.background = '#ff7c5c';
                        deleteBtn.dataset.confirm = '0';
                    }
                }, 3000);
            } else {
                const targetId = parseInt(deleteBtn.dataset.id);
                concerts = concerts.filter(c => parseInt(c.id) !== targetId);
                db.ref('concerts').set(concerts);
                showToast(t('toast_delete_event'));
            }
        }
    };
}

window.switchAdminTab = function (tab) {
    document.querySelectorAll('.admin-tab-btn').forEach(btn => {
        btn.classList.remove('active');
        if (btn.getAttribute('onclick').includes(tab)) btn.classList.add('active');
    });
    document.querySelectorAll('.admin-tab-content').forEach(content => content.classList.remove('active'));
    document.getElementById(`admin-tab-${tab}`).classList.add('active');
    if (tab === 'bookings') renderAdminBookings();
    if (tab === 'events') renderAdminEvents();
    if (tab === 'users') renderAdminUsers();
    if (tab === 'announcement') loadSavedAnnouncement();
};

window.updateBookingStatus = function (bookingId, newStatus) {
    const bIndex = bookings.findIndex(b => b.id == bookingId);
    if (bIndex !== -1) {
        bookings[bIndex].status = newStatus;
        db.ref('bookings').set(bookings);
        let statusText = newStatus;
        if (newStatus === "Pending") statusText = t('ticket_pending');
        if (newStatus === "Confirmed") statusText = t('ticket_confirmed');
        if (newStatus === "Failed") statusText = t('ticket_failed');
        showToast(`${t('toast_update_status')} ${statusText}`);
    }
};



function renderAdminBookings() {
    const tbody = document.querySelector('#admin-bookings-table tbody');
    if (!tbody) return;
    if (bookings.length === 0) {
        tbody.innerHTML = `<tr><td colspan="5" style="text-align:center;padding:30px;color:#96837b;">${t('empty_admin_bookings')}</td></tr>`;
        return;
    }

    // Group bookings by concertName
    const grouped = bookings.reduce((acc, b) => {
        if (!acc[b.concertName]) acc[b.concertName] = [];
        acc[b.concertName].push(b);
        return acc;
    }, {});

    let html = '';
    Object.keys(grouped).forEach(concertName => {
        const groupBookings = grouped[concertName];

        // Add Header Row for the group
        html += `
            <tr style="background: var(--pink-100);">
                <td colspan="5" style="padding: 10px 15px; font-weight: 800; color: var(--pink-600); border-left: 4px solid var(--pink-500);">
                    <i class="fas fa-music"></i> ${concertName} (${groupBookings.length} ${t('unit_item')})
                </td>
            </tr>
        `;

        // Add booking rows
        html += groupBookings.map(b => `
            <tr>
                <td onclick="openEditBookingModal('${b.id}')" style="cursor:pointer;">
                    <div style="font-weight:700; color:var(--pink-600);"><i class="fas fa-user-circle"></i> ${b.user || b.userName}</div>
                    <div style="font-size:0.65rem; color:#999;">ID: ${b.id}</div>
                </td>
                <td onclick="openEditBookingModal('${b.id}')" style="cursor:pointer; max-width:120px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap">${b.concertName}</td>
                <td onclick="openEditBookingModal('${b.id}')" style="cursor:pointer;">${b.zone1} <span style="color:var(--pink-500);font-weight:700">ร—${b.qty}</span></td>
                <td>
                    <select class="status-select" onchange="updateBookingStatus('${b.id}', this.value)">
                        <option value="Pending" ${b.status === 'Pending' ? 'selected' : ''}>โณ เธฃเธญ</option>
                        <option value="Confirmed" ${b.status === 'Confirmed' ? 'selected' : ''}>โ… เธเธญเธเน€เธเธดเธฃเนเธก</option>
                        <option value="Failed" ${b.status === 'Failed' ? 'selected' : ''}>โ เนเธกเนเธชเธณเน€เธฃเนเธ</option>
                    </select>
                </td>
                <td>
                    <button class="btn-icon btn-danger btn-delete-booking" data-id="${b.id}" data-confirm="0" style="padding:5px;width:30px;height:30px;">
                        <i class="fas fa-trash"></i>
                    </button>
                </td>
            </tr>`).join('');
    });

    tbody.innerHTML = html;

    tbody.onclick = function (e) {
        const deleteBtn = e.target.closest('.btn-delete-booking');
        if (deleteBtn) {
            e.stopPropagation();
            const confirmed = deleteBtn.dataset.confirm === '1';
            if (!confirmed) {
                deleteBtn.innerHTML = '<i class="fas fa-check"></i>';
                deleteBtn.style.background = '#dc2626';
                deleteBtn.dataset.confirm = '1';
                setTimeout(() => {
                    if (deleteBtn.dataset.confirm === '1') {
                        deleteBtn.innerHTML = '<i class="fas fa-trash"></i>';
                        deleteBtn.style.background = ''; // restore to CSS default
                        deleteBtn.dataset.confirm = '0';
                    }
                }, 3000);
            } else {
                const targetId = deleteBtn.dataset.id;
                bookings = bookings.filter(b => b.id != targetId);
                db.ref('bookings').set(bookings);
                showToast(t('toast_delete_booking'));
            }
        }
    };
}
function getRoleBadge(role) {
    if (!role) return '';
    let cls = '';
    let icon = '';
    let label = role;
    const roleLower = role.toLowerCase();

    if (roleLower.includes('admin miru') || roleLower.includes('admin focus')) {
        cls = 'badge-admin-special';
        icon = 'fa-crown';
        label = role;
    } else if (roleLower.includes('developer')) {
        cls = 'badge-developer';
        icon = 'fa-code';
        label = 'Developer';
    } else if (roleLower.includes('admin')) {
        cls = 'badge-admin';
        icon = 'fa-shield-halved';
        label = 'Admin';
    } else if (roleLower.includes('membership')) {
        cls = 'badge-membership';
        icon = 'fa-gem';
        label = 'Membership';
    } else if (roleLower.includes('เธฅเธนเธเธเนเธฒเธเธฃเธฐเธเธณ') || roleLower.includes('regular')) {
        cls = 'badge-regular';
        icon = 'fa-heart';
        label = 'Regular';
    } else if (roleLower.includes('เธฅเธนเธเธเธฃเธฐเธเนเธญเธ') || roleLower.includes('helper')) {
        cls = 'badge-helper';
        icon = 'fa-handshake-angle';
        label = 'Helper';
    } else {
        cls = 'badge-general';
        icon = 'fa-user';
        label = 'User';
    }

    return `<span class="role-badge ${cls}"><i class="fas ${icon}"></i> ${label}</span>`;
}

function renderAdminUsers() {
    const tbody = document.getElementById('admin-users-list');
    if (!tbody) return;

    if (users.length === 0) {
        tbody.innerHTML = `<tr><td colspan="4" style="text-align:center;padding:20px;">${t('empty_admin_users')}</td></tr>`;
        return;
    }

    const roles = [
        "Admin Miru", "Admin Focus", "Developer", "Membership", "Admin",
        "เธฅเธนเธเธเธฃเธฐเธเนเธญเธเธเนเธงเธขเธเธฒเธ", "เธฅเธนเธเธเนเธฒเธเธฃเธฐเธเธณ", "เธ—เธฑเนเธงเนเธ"
    ];

    // Helper to get translated role name for the select dropdown
    const getRoleName = (r) => {
        if (r === 'Developer') return t('role_developer');
        if (r === 'Membership') return t('role_membership');
        if (r === 'Admin') return t('role_admin');
        if (r === 'เธฅเธนเธเธเธฃเธฐเธเนเธญเธเธเนเธงเธขเธเธฒเธ') return t('role_helper');
        if (r === 'เธฅเธนเธเธเนเธฒเธเธฃเธฐเธเธณ') return t('role_regular');
        if (r === 'เธ—เธฑเนเธงเนเธ') return t('role_general');
        return r;
    };

    tbody.innerHTML = users.map(u => `
        <tr style="${u.banned ? 'opacity:0.6; background:#fff1f2;' : ''} transition: all 0.3s ease;">
            <td style="padding: 10px 8px; width: 60px;">
                <div style="font-weight:800; color:var(--pink-400); font-size:0.6rem; margin-bottom:1px;">UID</div>
                <div style="font-weight:700; color:var(--text-main); font-size:0.75rem;">#${u.id}</div>
                ${u.banned ? '<span style="color:#ef4444; font-size:0.55rem; font-weight:900; background:#fee2e2; padding:1px 4px; border-radius:4px; margin-top:2px; display:inline-block;">BANNED</span>' : ''}
            </td>
            <td style="padding: 10px 8px;">
                <div style="display:flex; align-items:center; gap:8px;">
                    <div style="width:30px; height:30px; border-radius:10px; background:linear-gradient(135deg, var(--pink-100), var(--pink-200)); display:flex; align-items:center; justify-content:center; color:var(--pink-500); font-weight:800; font-size:0.9rem; border:1px solid var(--pink-300); flex-shrink:0;">
                        ${u.name.charAt(0).toUpperCase()}
                    </div>
                    <div>
                        <div style="display:flex; align-items:center; gap:8px; white-space:nowrap;">
                            <span style="font-weight:800; color:var(--text-main); font-size:0.9rem;">${u.name}</span>
                            ${getRoleBadge(u.role)}
                        </div>
                    </div>
                </div>
            </td>
            <td style="padding: 10px 8px;">
                <div style="font-size:0.6rem; color:#999; font-weight:bold; margin-bottom:3px; text-transform:uppercase;">Role</div>
                <select onchange="updateUserRole(${u.id}, this.value)" class="premium-select" style="padding:4px 8px; border-radius:8px; border:1.2px solid var(--pink-200); font-size:0.75rem; width:100%; background:white; cursor:pointer; font-weight:600; outline:none;">
                    ${roles.map(r => `<option value="${r}" ${u.role === r ? 'selected' : ''}>${getRoleName(r)}</option>`).join('')}
                </select>
            </td>
            <td style="padding: 10px 8px;">
                <div style="display:flex; gap:6px; align-items:center; justify-content: flex-end;">
                    <button onclick="toggleBanUser(${u.id})" class="btn-action ${u.banned ? 'btn-unban' : 'btn-ban'}" title="${u.banned ? 'Unban' : 'Ban'}" style="width:28px; height:28px; font-size:0.8rem;">
                        <i class="fas ${u.banned ? 'fa-user-check' : 'fa-user-slash'}"></i>
                    </button>
                    <button onclick="deleteUser(${u.id})" class="btn-action btn-delete" title="Delete" style="width:28px; height:28px; font-size:0.8rem;">
                        <i class="fas fa-trash-alt"></i>
                    </button>
                </div>
            </td>
        </tr>
    `).join('');
}

window.updateUserRole = function (userId, newRole) {
    const u = users.find(x => x.id == userId);
    if (u) {
        // Update role locally first!
        u.role = newRole;

        // Push to Firebase
        db.ref('users').set(users).then(() => {
            // Update currentUser session if it's the same person
            if (currentUser && currentUser.id == userId) {
                currentUser.role = newRole;
                localStorage.setItem('currentUser', JSON.stringify(currentUser));
                restoreLoginUI();
                updateHomeUserStatus();
            }
            showToast(`${t('toast_update_role')} ${u.name} to ${newRole}`);
        }).catch(err => {
            alert("Firebase Update Error: " + err.message + "\n(Please check your Firebase Database Rules!)");
        });
    }
};

window.toggleBanUser = function (userId) {
    const u = users.find(x => x.id == userId);
    if (u) {
        u.banned = !u.banned;
        db.ref('users').set(users);
        showToast(`${u.banned ? t('toast_ban_success') : t('toast_unban_success')} ${u.name}`);
    }
};

window.deleteUser = function (userId) {
    if (userId === 1) return;
    if (confirm(t('confirm_delete_user'))) {
        users = users.filter(x => x.id != userId);
        db.ref('users').set(users);
        showToast(t('toast_delete_user'));
    }
};


function updateAdminStats() {
    const tickets = bookings.reduce((s, b) => s + b.qty, 0);
    const t = document.getElementById('stat-total-tickets');
    const e = document.getElementById('stat-active-events');
    if (t) t.innerText = tickets;
    if (e) e.innerText = concerts.length;
}

function showReviewInfo() { showToast(t('toast_review_loading')); }
function showHowToBook() { showToast(t('toast_howto_loading')); }

// ============================================================
// ANNOUNCEMENT MANAGEMENT
// ============================================================
const ANNOUNCE_COLORS = {
    'gradient-pink': 'linear-gradient(135deg, #ff4d8d, #e01e5a)',
    'gradient-purple': 'linear-gradient(135deg, #a855f7, #7c3aed)',
    'gradient-blue': 'linear-gradient(135deg, #3b82f6, #1d4ed8)',
    'gradient-green': 'linear-gradient(135deg, #10b981, #047857)',
    'gradient-orange': 'linear-gradient(135deg, #f97316, #c2410c)',
    'gradient-red': 'linear-gradient(135deg, #ef4444, #b91c1c)',
};

function getAnnouncementGradient(colorKey) {
    return ANNOUNCE_COLORS[colorKey] || ANNOUNCE_COLORS['gradient-pink'];
}

window.previewAnnouncement = function () {
    const text = document.getElementById('announce-text-input')?.value || '';
    const colorKey = document.getElementById('announce-color-select')?.value || 'gradient-pink';
    const preview = document.getElementById('announce-preview');
    const previewText = document.getElementById('announce-preview-text');
    if (!preview || !previewText) return;

    if (text.trim()) {
        previewText.innerText = text;
        preview.style.background = getAnnouncementGradient(colorKey);
        preview.style.display = 'flex';
    } else {
        preview.style.display = 'none';
    }
};

window.saveAnnouncement = function () {
    const text = document.getElementById('announce-text-input')?.value?.trim();
    const colorKey = document.getElementById('announce-color-select')?.value || 'gradient-pink';
    const visible = document.getElementById('announce-visible-select')?.value || 'show';

    if (!text) {
        showToast(t('toast_announce_empty'));
        return;
    }

    const announcementData = { text, colorKey, visible };
    localStorage.setItem('announcement', JSON.stringify(announcementData));

    applyAnnouncement(announcementData);
    updateAnnounceStatusUI(announcementData);
    showToast(t('toast_announce_saved'));
};

window.clearAnnouncement = function () {
    localStorage.removeItem('announcement');
    const banner = document.getElementById('announcement-banner');
    if (banner) banner.style.display = 'none';

    const textInput = document.getElementById('announce-text-input');
    if (textInput) textInput.value = '';

    const preview = document.getElementById('announce-preview');
    if (preview) preview.style.display = 'none';

    updateAnnounceStatusUI(null);
    showToast(t('toast_announce_cleared'));
};

function applyAnnouncement(data) {
    const banner = document.getElementById('announcement-banner');
    const bannerText = document.getElementById('banner-text');
    if (!banner || !bannerText) return;

    if (!data || data.visible === 'hide') {
        banner.style.display = 'none';
        return;
    }

    bannerText.innerText = data.text;
    banner.style.background = getAnnouncementGradient(data.colorKey);
    banner.style.display = 'flex';
}

function updateAnnounceStatusUI(data) {
    const statusText = document.getElementById('announce-status-text');
    if (!statusText) return;

    if (!data) {
        statusText.innerHTML = `<span style="color:#999;">${t('announce_empty')}</span>`;
        return;
    }

    const colorNames = {
        'gradient-pink': '๐ธ เธเธกเธเธน', 'gradient-purple': '๐’ เธกเนเธงเธ',
        'gradient-blue': '๐’ เธเนเธณเน€เธเธดเธ', 'gradient-green': '๐’ เน€เธเธตเธขเธง',
        'gradient-orange': '๐งก เธชเนเธก', 'gradient-red': 'โค๏ธ เนเธ”เธ'
    };

    const visibleLabel = data.visible === 'show'
        ? `<span style="color:#10b981; font-weight:700;">${t('announce_status_showing')}</span>`
        : `<span style="color:#ef4444; font-weight:700;">${t('announce_status_hidden')}</span>`;

    statusText.innerHTML = `
        เธเนเธญเธเธงเธฒเธก: <strong>"${data.text}"</strong> | 
        เธชเธต: ${colorNames[data.colorKey] || data.colorKey} | 
        เธชเธ–เธฒเธเธฐ: ${visibleLabel}
    `;
}

function loadSavedAnnouncement() {
    const saved = localStorage.getItem('announcement');
    if (!saved) return;
    try {
        const data = JSON.parse(saved);
        applyAnnouncement(data);

        // If admin panel is open, fill in the fields
        const textInput = document.getElementById('announce-text-input');
        const colorSelect = document.getElementById('announce-color-select');
        const visibleSelect = document.getElementById('announce-visible-select');
        if (textInput) textInput.value = data.text || '';
        if (colorSelect) colorSelect.value = data.colorKey || 'gradient-pink';
        if (visibleSelect) visibleSelect.value = data.visible || 'show';
        updateAnnounceStatusUI(data);
    } catch (e) {
        console.error('Failed to load announcement:', e);
    }
}

// ============================================================
// TOAST
// ============================================================
let toastTimer = null;
function showToast(msg) {
    const t = document.getElementById('toast');
    if (!t) return;
    t.innerText = msg;
    t.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => t.classList.remove('show'), 2800);
}

function openEditBookingModal(bookingId) {
    const b = bookings.find(x => x.id === bookingId);
    if (!b) return;

    document.getElementById('edit-booking-id').value = b.id;
    document.getElementById('edit-bk-name').value = b.userName;

    // Populate Concert Info
    const concert = concerts.find(c => c.id == b.concertId);
    if (concert) {
        document.getElementById('edit-bk-concert-img').src = concert.img;
        document.getElementById('edit-bk-concert-title').innerText = concert.title;
    } else {
        document.getElementById('edit-bk-concert-img').src = 'https://via.placeholder.com/70';
        document.getElementById('edit-bk-concert-title').innerText = b.concertName || 'เนเธกเนเธเธเธเนเธญเธกเธนเธฅเธเธฒเธ';
    }
    document.getElementById('edit-bk-status').value = b.status;
    document.getElementById('edit-bk-platform').value = b.platform || '';
    document.getElementById('edit-bk-user').value = b.user || '';
    document.getElementById('edit-bk-pass').value = b.pass || '';
    document.getElementById('edit-bk-email').value = b.email || '';
    document.getElementById('edit-bk-phone').value = b.phone || '';
    document.getElementById('edit-bk-twitter').value = b.twitter || '';
    document.getElementById('edit-bk-member').value = b.member || '';
    document.getElementById('edit-bk-showdate').value = b.showDate || '';
    document.getElementById('edit-bk-payment').value = b.payment || '';
    document.getElementById('edit-bk-zone1').value = b.zone1 || '';
    document.getElementById('edit-bk-price1').value = b.price1 || 0;
    document.getElementById('edit-bk-qty').value = b.qty || 1;
    document.getElementById('edit-bk-zone2').value = b.zone2 || '';
    document.getElementById('edit-bk-price2').value = b.price2 || 0;
    document.getElementById('edit-bk-name-t').value = b.nameT || '';
    document.getElementById('edit-bk-surname-t').value = b.surnameT || '';
    document.getElementById('edit-bk-note').value = b.note || '';

    // Trigger Thai date display
    window.updateAdminThaiDate(b.showDate);

    openModal('admin-booking');
}

function handleAdminBookingUpdate(e) {
    e.preventDefault();
    const id = document.getElementById('edit-booking-id').value;
    const idx = bookings.findIndex(x => x.id === id);
    if (idx === -1) return;

    bookings[idx] = {
        ...bookings[idx],
        status: document.getElementById('edit-bk-status').value,
        platform: document.getElementById('edit-bk-platform').value,
        user: document.getElementById('edit-bk-user').value,
        pass: document.getElementById('edit-bk-pass').value,
        email: document.getElementById('edit-bk-email').value,
        phone: document.getElementById('edit-bk-phone').value,
        twitter: document.getElementById('edit-bk-twitter').value,
        member: document.getElementById('edit-bk-member').value,
        showDate: document.getElementById('edit-bk-showdate').value,
        payment: document.getElementById('edit-bk-payment').value,
        zone1: document.getElementById('edit-bk-zone1').value,
        price1: document.getElementById('edit-bk-price1').value,
        qty: parseInt(document.getElementById('edit-bk-qty').value),
        zone2: document.getElementById('edit-bk-zone2').value,
        price2: document.getElementById('edit-bk-price2').value,
        nameT: document.getElementById('edit-bk-name-t').value,
        surnameT: document.getElementById('edit-bk-surname-t').value,
        note: document.getElementById('edit-bk-note').value,
        total: (parseInt(document.getElementById('edit-bk-price1').value) || 0) * parseInt(document.getElementById('edit-bk-qty').value)
    };

    db.ref('bookings').set(bookings);
    showToast(t('toast_update_booking'));
    closeModal('admin-booking');
}

// ============================================================
// VIEW MODE TOGGLE (Mobile / Web)
// ============================================================
function toggleViewMode() {
    const body = document.body;
    const isWeb = body.classList.toggle('web-mode');
    const btn = document.getElementById('mode-toggle');

    if (isWeb) {
        btn.innerHTML = '<i class="fas fa-desktop"></i>';
        showToast(t('toast_view_web'));
    } else {
        btn.innerHTML = '<i class="fas fa-mobile-alt"></i>';
        showToast(t('toast_view_mobile'));
    }
    localStorage.setItem('viewMode', isWeb ? 'web' : 'mobile');
}

// ============================================================
// DATA SYNC / MANAGEMENT (For moving between devices/Antigravity)
// ============================================================
window.exportDataToAntigravity = function () {
    const data = { concerts, bookings };
    const json = JSON.stringify(data);

    // Create a temporary textarea to copy text (Compatible with most browsers)
    const el = document.createElement('textarea');
    el.value = json;
    document.body.appendChild(el);
    el.select();
    document.execCommand('copy');
    document.body.removeChild(el);

    showToast(t('toast_copy_success'));
    alert(t('alert_copy_done'));
};

window.importDataFromAntigravity = function () {
    const json = prompt(t('prompt_import'));
    if (!json) return;

    try {
        const data = JSON.parse(json);
        if (data.concerts) {
            concerts = data.concerts;
            localStorage.setItem('concerts', JSON.stringify(concerts));
        }
        if (data.bookings) {
            bookings = data.bookings;
            localStorage.setItem('bookings', JSON.stringify(bookings));
        }
        showToast(t('toast_import_success'));
        setTimeout(() => location.reload(), 1000);
    } catch (e) {
        showToast(t('toast_import_fail'));
    }
};

// ============================================================
// WEBSITE STATUS / MAINTENANCE MODE
// ============================================================
function toggleSiteStatus(status) {
    const isMaintenance = (status === 'maintenance');
    const body = document.body;
    const statusText = document.getElementById('site-status-text');

    if (isMaintenance) {
        body.classList.add('maintenance-mode');
        if (statusText) {
            statusText.innerHTML = `โ— ${t('site_maintenance')}`;
            statusText.style.color = 'var(--pink-500)';
        }
        showToast(t('toast_site_offline'));
    } else {
        body.classList.remove('maintenance-mode');
        body.classList.remove('admin-view'); // Reset bypass
        if (statusText) {
            statusText.innerHTML = `โ— ${t('site_online')}`;
            statusText.style.color = '#10b981';
        }
        showToast(t('toast_site_online'));
    }

    // Push to Firebase
    db.ref('siteStatus').set(status);
}

function adminBypassMaintenance() {
    document.body.classList.add('admin-view');
    showSection('admin');
    showToast(t('toast_staff_mode'));
}

let secretClickCount = 0;
let secretClickTimer;
function handleSecretAdminClick() {
    secretClickCount++;
    clearTimeout(secretClickTimer);

    if (secretClickCount >= 5) {
        openModal('login'); // Open Login Modal instead of direct bypass
        showToast(t('toast_admin_login_req'));
        secretClickCount = 0;
    } else {
        secretClickTimer = setTimeout(() => {
            secretClickCount = 0;
        }, 3000); // 3 seconds timeout
    }
}

// Check initial status on load
document.addEventListener('DOMContentLoaded', () => {
    initLIFF(); // Initialize LIFF
    const savedStatus = localStorage.getItem('siteStatus') || 'online';
    const statusSelect = document.getElementById('admin-site-status');
    if (statusSelect) statusSelect.value = savedStatus;

    // Apply status but allow admin to keep seeing the admin panel
    if (savedStatus === 'maintenance') {
        document.body.classList.add('maintenance-mode');
        const statusText = document.getElementById('site-status-text');
        if (statusText) {
            statusText.innerHTML = `โ— ${t('site_maintenance')}`;
            statusText.style.color = 'var(--pink-500)';
        }
    }
});

// Check initial mode
if (localStorage.getItem('viewMode') === 'web') {
    document.body.classList.add('web-mode');
    document.addEventListener('DOMContentLoaded', () => {
        const btn = document.getElementById('mode-toggle');
        if (btn) btn.innerHTML = '<i class="fas fa-desktop"></i>';
    });
}
